\usetikzlibrary{arrows.meta,shapes,positioning}
\pagestyle{empty}

% ── WHO-Inspired Color Theme ──
\definecolor{primary}{HTML}{003F87}      % WHO deep blue
\definecolor{secondary}{HTML}{0071BC}    % WHO medium blue
\definecolor{accent}{HTML}{F5A623}       % Warm amber accent
\definecolor{accentteal}{HTML}{00897B}   % Teal for variety
\definecolor{bgposter}{HTML}{F4F7FB}     % Very light blue-white bg
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{E8F0FE}
\definecolor{statbg}{HTML}{DDEEFF}

% Card backgrounds (tinted)
\definecolor{bluebg}{HTML}{EBF3FB}
\definecolor{ambbg}{HTML}{FFF8ED}
\definecolor{greenbg}{HTML}{EAF5F3}
\definecolor{darkbg}{HTML}{E8EEF6}

% Card title bar backgrounds
\definecolor{bluetitlebg}{HTML}{D4E7F7}
\definecolor{ambtitlebg}{HTML}{FDEFD6}
\definecolor{greentitlebg}{HTML}{D4EDE9}
\definecolor{darktitlebg}{HTML}{C8D8ED}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=5pt, parsep=1pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=5pt, parsep=1pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  ambcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=ambbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent!80!black},
    coltitle=accent!80!black, colbacktitle=ambtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  greencard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=greenbg,
    borderline west={5pt}{0pt}{accentteal},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accentteal},
    coltitle=accentteal, colbacktitle=greentitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accentteal!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!14!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.20},
  },
  phasebox/.style={
    enhanced, arc=6pt, boxrule=2pt, colframe=#1,
    colback=#1!10!white, left=10pt, right=10pt,
    top=6pt, bottom=6pt,
    fonttitle=\fontsize{30}{36}\selectfont\bfseries\color{white},
    colbacktitle=#1, coltitle=white,
    toptitle=4pt, bottomtitle=4pt,
    valign=top,
  },
}

% Phase colors
\definecolor{phase1}{HTML}{0071BC}
\definecolor{phase2}{HTML}{F5A623}
\definecolor{phase3}{HTML}{E53935}
\definecolor{phase4}{HTML}{00897B}
\definecolor{phase5}{HTML}{5C6BC0}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

%% ══════════════════════════════
%% TITLE BAR
%% ══════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=28pt, right=28pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{62}{74}\selectfont\bfseries\color{white}
    COVID-19 Emergency Response}\\[6pt]
  {\fontsize{40}{50}\selectfont\bfseries\color{white!85}
    From Detection to Recovery}\\[8pt]
  {\fontsize{26}{34}\selectfont\color{white!70}
    WHO-Coordinated Five-Phase Framework \textbullet\; Global Pandemic Response Architecture}
}

%% ══════════════════════════════
%% STATS BANNER
%% ══════════════════════════════
\posterbox[
  enhanced, colback=statbg, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={3pt}{0pt}{primary!40},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{54}{64}\selectfont\bfseries\color{primary}194}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark}WHO Member States\\Coordinated}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{accent!60}{ambbg}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{38}{48}\selectfont\bfseries\color{accent!80!black}$\sim$1.9B}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark}COVAX Doses\\Delivered}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{secondary!50}{bluebg}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{42}{52}\selectfont\bfseries\color{secondary}200+}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark}Technical Guidance\\Documents Issued}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{accentteal!50}{greenbg}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{38}{48}\selectfont\bfseries\color{accentteal}6}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark}WHO Regions\\Covered}\vspace{5pt}%
    }}
  \end{minipage}
}

%% ══════════════════════════════
%% PHASE 1 — LEFT COL
%% ══════════════════════════════
\posterbox[bluecard, title={%
  \raisebox{1pt}{\tikz\node[circle,fill=phase1,text=white,
    inner sep=4pt,font=\fontsize{22}{26}\selectfont\bfseries]{1};}~
  Phase 1: Surveillance \& Early Detection}
]{name=phase1, column=1, between=row5 and row8}{
  \fontsize{28}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item National labs report unusual respiratory illness clusters via \textbf{IHR framework}
    \item WHO publishes \textbf{Disease Outbreak News} \& Weekly Epidemiological Records
    \item Real-time \textbf{COVID-19 Dashboard} tracks millions of data points daily
    \item First bulletin issued \textbf{5 January 2020} — days after Wuhan reports
  \end{itemize}
  \vspace{8pt}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \fontsize{26}{34}\selectfont\color{primary}
    \textbf{Key tool:} International Health Regulations (IHR) — legally binding framework across 196 States
  }}
}

%% ══════════════════════════════
%% PHASE 2 — LEFT COL
%% ══════════════════════════════
\posterbox[ambcard, title={%
  \raisebox{1pt}{\tikz\node[circle,fill=phase2,text=white,
    inner sep=4pt,font=\fontsize{22}{26}\selectfont\bfseries]{2};}~
  Phase 2: Risk Assessment \& Alert}
]{name=phase2, column=1, between=row8 and row11}{
  \fontsize{28}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Rapid assessment of \textbf{spread likelihood}, illness severity, \& health system capacity
    \item Regular situation reports issued to all Member States
    \item Independent Oversight \& Advisory Committee reviews alert mechanisms
  \end{itemize}
  \vspace{8pt}
  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \fontsize{26}{34}\selectfont\color{accent!80!black}
    \textbf{Milestone:} PHEIC declared \textbf{30 January 2020} — Public Health Emergency of International Concern
  }}
}

%% ══════════════════════════════
%% PHASE 3 — LEFT COL
%% ══════════════════════════════
\posterbox[darkcard, title={%
  \raisebox{1pt}{\tikz\node[circle,fill=phase3,text=white,
    inner sep=4pt,font=\fontsize{22}{26}\selectfont\bfseries]{3};}~
  Phase 3: Response Operations \& Clinical Management}
]{name=phase3, column=1, between=row11 and row16}{
  \fontsize{28}{38}\selectfont
  WHO mobilizes technical teams across \textbf{5 response pillars}:

  \vspace{6pt}
  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \fontsize{26}{34}\selectfont\color{primary}
    \textbf{Infection Prevention \& Control} — PPE guidance, hand hygiene, decontamination
  }}\vspace{4pt}

  \colorbox{primary!12}{\parbox{0.94\linewidth}{%
    \fontsize{26}{34}\selectfont\color{textdark}
    \textbf{Clinical Management} — Treatment protocols, oxygen therapy, ICU guidelines
  }}\vspace{4pt}

  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \fontsize{26}{34}\selectfont\color{primary}
    \textbf{Health Workforce} — Training, surge staffing, mental health support
  }}\vspace{4pt}

  \colorbox{primary!12}{\parbox{0.94\linewidth}{%
    \fontsize{26}{34}\selectfont\color{textdark}
    \textbf{Supply Chain \& Logistics} — Essential medicines, diagnostics, equipment
  }}\vspace{4pt}

  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \fontsize{26}{34}\selectfont\color{primary}
    \textbf{Research \& Innovation} — Solidarity Trial, vaccine R\&D coordination
  }}

  \vspace{8pt}
  {\fontsize{26}{34}\selectfont\color{textgray}
    Partners: UNICEF \textbullet\; World Bank \textbullet\; Médecins Sans Frontières}
}

%% ══════════════════════════════
%% KEY MESSAGE FOOTER — LEFT COL
%% ══════════════════════════════
\posterbox[highlightcard, title={Global Coordination at Unprecedented Scale}
]{name=keymsg, column=1, between=row16 and bottom}{
  \fontsize{28}{38}\selectfont\color{textdark}
  \begin{itemize}[itemsep=8pt]
    \item \textbf{194} WHO Member States follow same structured framework
    \item \textbf{6 regions} coordinated through Health Emergencies Programme
    \item Response guided by \textbf{200+ technical documents} across all phases
    \item COVID-19 dashboard: \textbf{millions of data points} tracked daily
  \end{itemize}
  \vspace{6pt}
  \colorbox{white!60}{\parbox{0.94\linewidth}{%
    \fontsize{24}{32}\selectfont\color{primary}
    \textit{``This process-flow represents a coordinated global health architecture designed to save lives and build resilience against future pandemics.'' — WHO}
  }}
}

%% ══════════════════════════════
%% FLOW DIAGRAM — RIGHT COL TOP
%% ══════════════════════════════
\posterbox[
  enhanced, colback=white, arc=4pt,
  boxrule=1pt, colframe=primary!30,
  left=10pt, right=10pt, top=8pt, bottom=8pt,
  drop shadow={opacity=0.12},
]{name=flowdiag, column=2, between=row5 and row12}{
  \centering
  {\fontsize{30}{38}\selectfont\bfseries\color{primary}Five-Phase Response Process Flow}\\[10pt]

  % Phase flow using tikz
  \begin{tikzpicture}[
    node distance=8mm,
    pnode/.style={rectangle, rounded corners=4pt, minimum width=58mm,
                  minimum height=14mm, align=center, text=white,
                  font=\fontsize{22}{28}\selectfont\bfseries},
    arrow/.style={-{Stealth[length=5mm,width=3mm]}, line width=2.5pt, color=primary!60},
    label/.style={font=\fontsize{19}{24}\selectfont\color{textgray}, align=left, text width=46mm},
  ]

    \node[pnode, fill=phase1] (p1) {\textbf{Phase 1}\\Surveillance \& Detection};
    \node[pnode, fill=phase2, below=of p1] (p2) {\textbf{Phase 2}\\Risk Assessment \& Alert};
    \node[pnode, fill=phase3, below=of p2] (p3) {\textbf{Phase 3}\\Response Operations};
    \node[pnode, fill=phase4, below=of p3] (p4) {\textbf{Phase 4}\\Public Health Measures};
    \node[pnode, fill=phase5, below=of p4] (p5) {\textbf{Phase 5}\\Recovery \& Resilience};

    \draw[arrow] (p1) -- (p2);
    \draw[arrow] (p2) -- (p3);
    \draw[arrow] (p3) -- (p4);
    \draw[arrow] (p4) -- (p5);

    % Side labels
    \node[label, right=14mm of p1] {IHR reporting\\Disease Outbreak News\\Jan 5, 2020};
    \node[label, right=14mm of p2] {Rapid risk assessment\\Situation reports\\PHEIC: Jan 30, 2020};
    \node[label, right=14mm of p3] {5 response pillars\\WHO + UNICEF + WB\\Clinical protocols};
    \node[label, right=14mm of p4] {Testing \& tracing\\Vaccination (COVAX)\\Risk communication};
    \node[label, right=14mm of p5] {Restore services\\After-action reviews\\Long COVID support};

  \end{tikzpicture}
}

%% ══════════════════════════════
%% PHASE 4 — RIGHT COL
%% ══════════════════════════════
\posterbox[greencard, title={%
  \raisebox{1pt}{\tikz\node[circle,fill=phase4,text=white,
    inner sep=4pt,font=\fontsize{22}{26}\selectfont\bfseries]{4};}~
  Phase 4: Public Health \& Social Measures}
]{name=phase4, column=2, between=row12 and row16}{
  \fontsize{28}{38}\selectfont
  \begin{itemize}[itemsep=9pt]
    \item \textbf{Testing \& Contact Tracing} — PCR + rapid antigen; digital \& manual tracing
    \item \textbf{Quarantine \& Isolation} — Evidence-based guidelines, updated per variant
    \item \textbf{Risk Communication} — Multilingual campaigns, combating misinformation
  \end{itemize}

  \vspace{8pt}
  \colorbox{accentteal!22}{\parbox{0.94\linewidth}{%
    \fontsize{30}{40}\selectfont\bfseries\color{accentteal}
    $\sim$1.9 Billion COVAX Doses
  }}\\[4pt]
  \colorbox{accentteal!12}{\parbox{0.94\linewidth}{%
    \fontsize{26}{34}\selectfont\color{textdark}
    Delivered to \textbf{146 countries} by mid-2023, prioritizing health workers \& vulnerable populations
  }}
}

%% ══════════════════════════════
%% PHASE 5 — RIGHT COL
%% ══════════════════════════════
\posterbox[bluecard, title={%
  \raisebox{1pt}{\tikz\node[circle,fill=phase5,text=white,
    inner sep=4pt,font=\fontsize{22}{26}\selectfont\bfseries]{5};}~
  Phase 5: Recovery \& Health System Resilience}
]{name=phase5, column=2, between=row16 and bottom}{
  \fontsize{28}{38}\selectfont
  \begin{itemize}[itemsep=9pt]
    \item \textbf{Restore} routine health services disrupted during pandemic
    \item \textbf{Strengthen preparedness} through updated national action plans
    \item \textbf{Address long COVID} \& mental health impacts
    \item \textbf{After-action reviews} to capture lessons learned for future outbreaks
  \end{itemize}

  \vspace{8pt}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \fontsize{26}{34}\selectfont\color{primary}
    \textbf{Outcome:} A health system more resilient, better prepared for the next pandemic threat
  }}
}

\end{tcbposter}
\end{document}

